      }
    } catch {}
    try {
      await gh('DELETE', STORAGE_REPO, `/git/refs/tags/${encodeURIComponent(relTag)}`);
      parts.push(`Tag \`${relTag}\``);
    } catch {}
    try {
      await gh('DELETE', STORAGE_REPO, `/git/refs/heads/${encodeURIComponent(stBranch)}`);
      parts.push(`Nhánh \`${stBranch}\``);
